q1.rq (discarded):
SELECT ?star ?wgsn ?en ?sv ?con ?conEn ?conSv ?mag ?band ?bandLabel ?magRank WHERE {
  ?star wdt:P2275 ?wgsn .
  OPTIONAL { ?star wdt:P59 ?con .
             OPTIONAL { ?con rdfs:label ?conEn FILTER(LANG(?conEn) = "en") }
             OPTIONAL { ?con rdfs:label ?conSv FILTER(LANG(?conSv) = "sv") } }
  OPTIONAL { ?star p:P1215 ?ms . ?ms psv:P1215/wikibase:quantityAmount ?mag ; wikibase:rank ?magRank .
             OPTIONAL { ?ms pq:P1227 ?band . OPTIONAL { ?band rdfs:label ?bandLabel FILTER(LANG(?bandLabel) = "en") } } }
  OPTIONAL { ?star rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?star rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
}

q2.rq (timed out):
SELECT ?star ?en ?sv ?mul ?mag ?magRank ?con ?conEn ?conSv ?hip WHERE {
  ?star p:P1215 ?ms .
  ?ms psv:P1215/wikibase:quantityAmount ?mag ; pq:P1227 wd:Q4892529 ; wikibase:rank ?magRank .
  FILTER(?mag < 2.6 && ?magRank != wikibase:DeprecatedRank)
  OPTIONAL { ?star wdt:P59 ?con .
             OPTIONAL { ?con rdfs:label ?conEn FILTER(LANG(?conEn) = "en") }
             OPTIONAL { ?con rdfs:label ?conSv FILTER(LANG(?conSv) = "sv") } }
  OPTIONAL { ?star p:P528 ?cs . ?cs ps:P528 ?hip ; pq:P972 wd:Q537199 . }
  OPTIONAL { ?star rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?star rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?star rdfs:label ?mul FILTER(LANG(?mul) = "mul") }
}
ORDER BY ?mag

